module rom_tb;

// === Global Sync Signal ===
reg llm_go_signal = 1;


    reg [7:0] addr_tb;          // Address input for the ROM
    wire [15:0] dout_tb;        // Data output from the ROM

    ROM rom_inst (
        .addr(addr_tb),
        .dout(dout_tb)
    );

    integer error;

    initial begin
        // Initialize simulation
        $display("Starting ROM Testbench...");
        error = 0;

        // Test reading data from different memory locations
        addr_tb = 8'h00;  // Read from address 0
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

        #10;
        if (dout_tb !== 16'hA0A0) begin
            $display("Error: Data read from address 0 is incorrect");
            error = error + 1;
        end

        addr_tb = 8'h01;  // Read from address 1
        #10;
        if (dout_tb !== 16'hB1B1) begin
            $display("Error: Data read from address 1 is incorrect");
            error = error + 1;
        end

        addr_tb = 8'h02;  // Read from address 2
        #10;
        if (dout_tb !== 16'hC2C2) begin
            $display("Error: Data read from address 2 is incorrect");
            error = error + 1;
        end

        addr_tb = 8'h03;  // Read from address 3
        #10;
        if (dout_tb !== 16'hD3D3) begin
            $display("Error: Data read from address 3 is incorrect");
            error = error + 1;
        end

        // Add more test cases here if needed

        // Check for errors
        if (error == 0) begin
            $display("=========== Your Design Passed ===========");
        end else begin
            $display("Test completed with %d errors.", error);
        end

        $finish;
    end





        ///////////////////added
        integer file_mantra;
        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      $fwrite(file_mantra, "dout_tb,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", dout_tb);

            $fwrite(file_mantra, "\n");
          end
        end





// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. THEN WAIT for original tests
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    $display("LLM: Starting ROM Mutation Tests...");

    // ---------------------------------------------------------
    // Phase 1: Known Data Verification (Addresses 0-3)
    // ---------------------------------------------------------
    // These addresses have hardcoded values in the DUT.
    // Testing them verifies basic read functionality and detects
    // simple operator mutations (e.g., addr+1, addr-1).
    addr_tb = 8'h00; #10; // Expect 16'hA0A0
    addr_tb = 8'h01; #10; // Expect 16'hB1B1
    addr_tb = 8'h02; #10; // Expect 16'hC2C2
    addr_tb = 8'h03; #10; // Expect 16'hD3D3

    // ---------------------------------------------------------
    // Phase 2: Walking 1s (Bit-Level Fault Localization)
    // ---------------------------------------------------------
    // Excites each address bit individually.
    // Detects stuck-at-0 faults on address lines and bit-select errors.
    addr_tb = 8'h01; #10; // Bit 0
    addr_tb = 8'h02; #10; // Bit 1
    addr_tb = 8'h04; #10; // Bit 2
    addr_tb = 8'h08; #10; // Bit 3
    addr_tb = 8'h10; #10; // Bit 4
    addr_tb = 8'h20; #10; // Bit 5
    addr_tb = 8'h40; #10; // Bit 6
    addr_tb = 8'h80; #10; // Bit 7 (MSB)

    // ---------------------------------------------------------
    // Phase 3: Walking 0s (Inverse Bit-Level Faults)
    // ---------------------------------------------------------
    // Excites all bits except one.
    // Detects stuck-at-1 faults on address lines.
    addr_tb = 8'hFE; #10; // ~Bit 0
    addr_tb = 8'hFD; #10; // ~Bit 1
    addr_tb = 8'hFB; #10; // ~Bit 2
    addr_tb = 8'hF7; #10; // ~Bit 3
    addr_tb = 8'hEF; #10; // ~Bit 4
    addr_tb = 8'hDF; #10; // ~Bit 5
    addr_tb = 8'hBF; #10; // ~Bit 6
    addr_tb = 8'h7F; #10; // ~Bit 7

    // ---------------------------------------------------------
    // Phase 4: Alternating Patterns & Boundaries
    // ---------------------------------------------------------
    // Maximizes switching activity and tests full range.
    addr_tb = 8'h55; #10; // 01010101
    addr_tb = 8'hAA; #10; // 10101010
    addr_tb = 8'h00; #10; // Min Boundary
    addr_tb = 8'hFF; #10; // Max Boundary

    // ---------------------------------------------------------
    // Phase 5: Rapid Transitions
    // ---------------------------------------------------------
    // Back-to-back reads of disparate addresses to expose timing/latching issues.
    addr_tb = 8'h00; #10;
    addr_tb = 8'hFF; #10;
    addr_tb = 8'h00; #10;

    // 4. Cleanup / Handover
    $display("LLM: Tests Finished. Handing over...");
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule

